const results = await Promise.allSettled([
  tools.exec_command({cmd:"rg --files -g '!node_modules' -g '!.git' | sed -n '1,120p'; if [ -f package.json ]; then sed -n '1,220p' package.json; fi","max_output_tokens":5000}),
  tools.web__run({open:[{ref_id:"https://docs.typesafe.ai/sdk/typescript"},{ref_id:"https://docs.typesafe.ai/api-reference/system-one"},{ref_id:"https://github.com/typesafe-ai/typesafe-sdk-js"}],response_length:"long"})
]); for (const r of results) { if (r.status === "fulfilled") text(r.value); else text(String(r.reason)); }
